    "Burning of fuel and industrial activities are important causes of air pollution.",
    "Important air pollutants include particulate matter, carbon monoxide, ozone, nitrogen dioxide and sulfur dioxide.",
    "Water pollution can result from industrial waste, oil spills, pesticides, insecticides, detergents, domestic waste, mining and agricultural runoff.",
    "Eutrophication involves excessive nutrient enrichment of a water body and can reduce dissolved oxygen.",
    "Soil pollution may result from pesticides, insecticides, industrial waste, mining and poor waste disposal.",
    "Noise pollution can result from machinery, traffic, construction, generators, loud music and other excessive sound sources.",
    "Radioactive pollution can result from nuclear accidents, radioactive waste and improper handling of radioactive materials.",
    "Thermal pollution involves an undesirable change in environmental temperature, especially in water bodies.",
    "Light pollution involves excessive or unwanted artificial illumination.",
    "Pollution can move through air, water, soil, groundwater and biological systems.",
    "Pollution is closely connected with geology through porosity, permeability, fractures, faults, weathering and groundwater flow.",
    "Mining activities can contribute to land, water and air pollution if wastes and emissions are poorly managed.",
