        "Hazard maps can identify areas that are relatively safe, moderately hazardous or highly hazardous.",
        "Land-use planning uses this information to guide decisions about where buildings, roads, industries and other infrastructure should or should not be located.",
        "For example, development can be restricted in highly unstable slopes, active flood-prone channels, known fault zones or areas susceptible to ground collapse.",
        "Good land-use planning is one of the most effective ways of reducing exposure to geologic hazards."
