        "After a suitable thin section has been prepared and placed on the microscope, the student can examine the mineral first under PPL and then under XPL.",
        "Under PPL, observations can include colour, relief, cleavage, habit, pleochroism and absorption.",
        "Under XPL, the student can investigate whether the mineral is isotropic or anisotropic and observe features such as birefringence, interference colours, extinction and twinning.",
        "The observations can then be compared and combined to assist mineral identification."
