export function getTopicsForCourse(courseCode) {
  return topicsByCourse[courseCode] ?? [];
}

export function getTopic(courseCode, topicId) {
  return getTopicsForCourse(courseCode).find(
    (topic) => topic.id === topicId
  ) ?? null;
}